<script setup lang="ts">
import { uiText } from '@/i18n'

import { onMounted,onBeforeUnmount,ref } from 'vue'
import { workflowApi,type WorkflowPreferences } from '@/api/workflows'
import { authStore } from '@/stores/auth'
const value=ref<WorkflowPreferences>(),busy=ref(false),error=ref(''),saved=ref(false)
let active=true;const owner=authStore.state.user?.id,days=['周日','周一','周二','周三','周四','周五','周六']
onBeforeUnmount(()=>{active=false})
async function load(){try{const p=await workflowApi.preferences();if(active&&owner===authStore.state.user?.id){if(!p.revision)p.zoneId=Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';value.value=p}}catch(e){if(active)error.value=(e as Error).message}}
onMounted(load)
function day(n:number){if(!value.value)return;value.value.studyDays=value.value.studyDays.includes(n)?value.value.studyDays.filter(d=>d!==n):[...value.value.studyDays,n].sort()}
async function save(){if(busy.value||!value.value)return;busy.value=true;error.value='';saved.value=false;try{const p=await workflowApi.savePreferences(value.value);if(active&&owner===authStore.state.user?.id){value.value=p;saved.value=true;window.dispatchEvent(new Event('personal-platform:notifications-changed'))}}catch(e){if(active)error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><article class="panel settings-card"><header><div><h3>{{ uiText('通知与学习计划') }}</h3><p>{{ uiText('仅影响自己的提醒；关闭提醒后，消息和学习记录仍然保存。') }}</p></div></header><p v-if="error" class="form-error" role="alert">{{ uiText(error) }} <button class="button button--ghost" @click="load">{{ uiText('重新加载') }}</button></p><form v-if="value" class="settings-form" @submit.prevent="save"><fieldset class="workflow-toggles" :disabled="busy"><legend>{{ uiText('提醒范围') }}</legend><label><input v-model="value.groups" type="checkbox" />{{ uiText('群组消息与邀请') }}</label><label><input v-model="value.contacts" type="checkbox" />{{ uiText('联系人请求与聊天') }}</label><label><input v-model="value.mail" type="checkbox" />{{ uiText('站内信') }}</label><label><input v-model="value.study" type="checkbox" />{{ uiText('笔记复习') }}</label></fieldset><label class="field-label">{{ uiText('每周练习目标（答题次数）') }}<input v-model.number="value.weeklyTarget" class="field-input" type="number" min="5" max="7000" required :disabled="busy" /></label><fieldset class="workflow-days" :disabled="busy"><legend>{{ uiText('计划学习日') }}</legend><button v-for="(label,n) in days" :key="n" type="button" :aria-pressed="value.studyDays.includes(n)" @click="day(n)">{{ uiText(label) }}</button></fieldset><p>{{ uiText('每天可照常学习。学习日期按') }} {{value.zoneId}} {{ uiText('记录，默认取浏览器时区。') }}</p><p v-if="saved" role="status">{{ uiText('设置已保存。') }}</p><button class="button button--dark" :disabled="busy||!value.studyDays.length">{{busy?uiText('正在保存…'):uiText('保存设置')}}</button></form></article></template>
<style scoped>fieldset{padding:0;border:0}legend{margin-bottom:12px;font-weight:600}.workflow-toggles{display:grid;gap:12px}.workflow-toggles label{display:flex;gap:10px}.workflow-days{display:flex;gap:6px;flex-wrap:wrap}.workflow-days button{padding:8px 12px;border:1px solid var(--line);border-radius:4px;background:transparent;cursor:pointer}.workflow-days button[aria-pressed=true]{background:var(--green);color:white}</style>
